-- 한글 깨짐 방지: psql이 입력 스트림을 UTF-8로 해석 (PowerShell 파이프 깨짐 방어)
SET client_encoding TO 'UTF8';

BEGIN;

-- =============================================
-- 기존 더미 데이터 삭제 (email LIKE dummy_% 로 안전 분리)
-- =============================================
DELETE FROM journal_strategy_tags WHERE journal_id IN (SELECT id FROM trade_journals WHERE user_id IN (SELECT id FROM users WHERE email LIKE 'dummy_%'));
DELETE FROM trade_journals   WHERE user_id IN (SELECT id FROM users WHERE email LIKE 'dummy_%');
DELETE FROM strategy_tags    WHERE user_id IN (SELECT id FROM users WHERE email LIKE 'dummy_%');
DELETE FROM positions        WHERE user_id IN (SELECT id FROM users WHERE email LIKE 'dummy_%');
DELETE FROM trades           WHERE user_id IN (SELECT id FROM users WHERE email LIKE 'dummy_%');
DELETE FROM exchange_keys    WHERE user_id IN (SELECT id FROM users WHERE email LIKE 'dummy_%');
DELETE FROM refresh_tokens   WHERE user_id IN (SELECT id FROM users WHERE email LIKE 'dummy_%');
DELETE FROM users            WHERE email LIKE 'dummy_%';

